'use strict';
/* Standalone host for the existing, integrity-checked CLEA v1 conversation UI.
 * No question, reply, model weights or runtime policy is generated by this file.
 */
(function () {
  const failedScripts = new Set();
  let started = false;

  function scriptName(target) {
    try { return new URL(target.src, location.href).pathname.split('/').pop(); }
    catch { return 'datoteka razgovora'; }
  }

  function fail(message) {
    const error = document.getElementById('conversation-load-error');
    if (!error) return;
    error.hidden = false;
    error.replaceChildren();
    const heading = document.createElement('strong');
    heading.textContent = 'Razgovor nije pokrenut';
    const description = document.createElement('p');
    description.textContent = message;
    const retry = document.createElement('button');
    retry.type = 'button';
    retry.textContent = 'Ponovo učitaj stranicu';
    retry.addEventListener('click', function () { location.reload(); });
    error.append(heading, description, retry);
    const root = document.getElementById('clea-chat');
    root?.querySelectorAll('button, input, textarea, select').forEach(function (control) { control.disabled = true; });
    const ready = document.getElementById('chat-ready');
    if (ready) ready.textContent = 'Model nije pokrenut';
  }

  // This file executes before the deferred runtime assets so resource failures
  // can be reported even when the shared UI cannot construct its own status.
  window.addEventListener('error', function (event) {
    if (event.target instanceof HTMLScriptElement) {
      failedScripts.add(scriptName(event.target));
      if (started) fail('Nije učitana potrebna datoteka: ' + [...failedScripts].join(', ') + '. Provjeri vezu i ponovo učitaj stranicu.');
    }
  }, true);

  async function start() {
    if (started) return;
    started = true;
    if (failedScripts.size) {
      fail('Nije učitana potrebna datoteka: ' + [...failedScripts].join(', ') + '. Provjeri vezu i ponovo učitaj stranicu.');
      return;
    }
    let hostConfig=null;try{hostConfig=await window.CLEA7AI?.configuration();}catch{}
    const runtimeHost=window.CLEA7AI?.isRuntimeHost(hostConfig)===true;
    if (!window.isSecureContext || (!runtimeHost&&!window.crypto?.subtle)) {
      fail('Za provjeru integriteta modela potreban je siguran HTTPS preglednik s podrškom za Web Crypto. Otvori ovu stranicu direktno u ažuriranom pregledniku.');
      return;
    }
    if (!runtimeHost&&typeof window.Worker !== 'function') {
      fail('Ovaj preglednik ne podržava Web Worker potreban za lokalni model. Otvori stranicu u ažuriranom samostalnom pregledniku.');
      return;
    }
    if (!window.CLEA7 || !window.CLEA7Core || !window.CLEA7CACI || !window.CLEA7ChatAssets || !window.CLEA7Chat || !window.CLEA7ChatWorkspace) {
      fail('CLEA izvršno jezgro ili razgovorni modul nije ispravno učitan. Odgovori nisu pokrenuti; ponovo učitaj stranicu.');
      return;
    }

    const root = document.getElementById('clea-chat');
    const shell = root?.querySelector('.clea-chat-shell');
    const inspector = root?.querySelector('.clea-chat-inspector');
    const retry = document.getElementById('chat-retry');
    if (!shell || !inspector || !retry) {
      fail('Nije pripremljen interfejs razgovora. Ponovo učitaj stranicu.');
      return;
    }

    // Move the actual diagnostics nodes; never recreate controls or listeners.
    const diagnostics = document.createElement('details');
    diagnostics.id = 'conversation-diagnostics';
    const summary = document.createElement('summary');
    summary.textContent = 'Kako radi model i privatnost';
    diagnostics.append(summary, inspector);
    shell.append(diagnostics);

    // The real UI owns loading, readiness, cancellation and errors. Expose its
    // retry control automatically when loading fails, without inventing a reply.
    const ready = document.getElementById('chat-ready');
    const observer = new MutationObserver(function () {
      if (ready.textContent === 'Model nije pokrenut') diagnostics.open = true;
    });
    observer.observe(ready, { childList: true, characterData: true, subtree: true });
    window.addEventListener('beforeunload', function () { observer.disconnect(); }, { once: true });
    retry.click();
  }

  if (document.readyState === 'complete') start();
  else document.addEventListener('DOMContentLoaded', start, { once: true });
})();
